      PacketTwoBContractVector(operation: 1'u8, xHigh: 0xffff800000000000'u64, xLow: 0x0000000000000002'u64, yHigh: 0x3fff000000000000'u64, yLow: 0x0000000000000001'u64, expectedHigh: 0xffff800000000000'u64, expectedLow: 0x0000000000000002'u64, expectedSignFlip: false, expectedHalfTie: false),
      PacketTwoBContractVector(operation: 1'u8, xHigh: 0xffff800000000000'u64, xLow: 0x0000000000000002'u64, yHigh: 0xbfff000000000000'u64, yLow: 0x0000000000000001'u64, expectedHigh: 0xffff800000000000'u64, expectedLow: 0x0000000000000002'u64, expectedSignFlip: false, expectedHalfTie: false),
      PacketTwoBContractVector(operation: 1'u8, xHigh: 0xffff800000000000'u64, xLow: 0x0000000000000002'u64, yHigh: 0x3fff800000000000'u64, yLow: 0x0000000000000000'u64, expectedHigh: 0xffff800000000000'u64, expectedLow: 0x0000000000000002'u64, expectedSignFlip: false, expectedHalfTie: false),
      PacketTwoBContractVector(operation: 1'u8, xHigh: 0xffff800000000000'u64, xLow: 0x0000000000000002'u64, yHigh: 0xbfff800000000000'u64, yLow: 0x0000000000000000'u64, expectedHigh: 0xffff800000000000'u64, expectedLow: 0x0000000000000002'u64, expectedSignFlip: false, expectedHalfTie: false),
      PacketTwoBContractVector(operation: 1'u8, xHigh: 0xffff800000000000'u64, xLow: 0x0000000000000002'u64, yHigh: 0x4000000000000000'u64, yLow: 0x0000000000000000'u64, expectedHigh: 0xffff800000000000'u64, expectedLow: 0x0000000000000002'u64, expectedSignFlip: false, expectedHalfTie: false),
      PacketTwoBContractVector(operation: 1'u8, xHigh: 0xffff800000000000'u64, xLow: 0x0000000000000002'u64, yHigh: 0xc000000000000000'u64, yLow: 0x0000000000000000'u64, expectedHigh: 0xffff800000000000'u64, expectedLow: 0x0000000000000002'u64, expectedSignFlip: false, expectedHalfTie: false),
      PacketTwoBContractVector(operation: 1'u8, xHigh: 0xffff800000000000'u64, xLow: 0x0000000000000002'u64, yHigh: 0x4000800000000000'u64, yLow: 0x0000000000000000'u64, expectedHigh: 0xffff800000000000'u64, expectedLow: 0x0000000000000002'u64, expectedSignFlip: false, expectedHalfTie: false),
      PacketTwoBContractVector(operation: 1'u8, xHigh: 0xffff800000000000'u64, xLow: 0x0000000000000002'u64, yHigh: 0xc000800000000000'u64, yLow: 0x0000000000000000'u64, expectedHigh: 0xffff800000000000'u64, expectedLow: 0x0000000000000002'u64, expectedSignFlip: false, expectedHalfTie: false),
      PacketTwoBContractVector(operation: 1'u8, xHigh: 0xffff800000000000'u64, xLow: 0x0000000000000002'u64, yHigh: 0x4001400000000000'u64, yLow: 0x0000000000000000'u64, expectedHigh: 0xffff800000000000'u64, expectedLow: 0x0000000000000002'u64, expectedSignFlip: false, expectedHalfTie: false),
      PacketTwoBContractVector(operation: 1'u8, xHigh: 0xffff800000000000'u64, xLow: 0x0000000000000002'u64, yHigh: 0xc001400000000000'u64, yLow: 0x0000000000000000'u64, expectedHigh: 0xffff800000000000'u64, expectedLow: 0x0000000000000002'u64, expectedSignFlip: false, expectedHalfTie: false),
      PacketTwoBContractVector(operation: 1'u8, xHigh: 0xffff800000000000'u64, xLow: 0x0000000000000002'u64, yHigh: 0x7ffeffffffffffff'u64, yLow: 0xffffffffffffffff'u64, expectedHigh: 0xffff800000000000'u64, expectedLow: 0x0000000000000002'u64, expectedSignFlip: false, expectedHalfTie: false),
      PacketTwoBContractVector(operation: 1'u8, xHigh: 0xffff800000000000'u64, xLow: 0x0000000000000002'u64, yHigh: 0xfffeffffffffffff'u64, yLow: 0xffffffffffffffff'u64, expectedHigh: 0xffff800000000000'u64, expectedLow: 0x0000000000000002'u64, expectedSignFlip: false, expectedHalfTie: false),
      PacketTwoBContractVector(operation: 1'u8, xHigh: 0xffff800000000000'u64, xLow: 0x0000000000000002'u64, yHigh: 0x7fff000000000000'u64, yLow: 0x0000000000000000'u64, expectedHigh: 0xffff800000000000'u64, expectedLow: 0x0000000000000002'u64, expectedSignFlip: false, expectedHalfTie: false),
      PacketTwoBContractVector(operation: 1'u8, xHigh: 0xffff800000000000'u64, xLow: 0x0000000000000002'u64, yHigh: 0xffff000000000000'u64, yLow: 0x0000000000000000'u64, expectedHigh: 0xffff800000000000'u64, expectedLow: 0x0000000000000002'u64, expectedSignFlip: false, expectedHalfTie: false),
      PacketTwoBContractVector(operation: 1'u8, xHigh: 0xffff800000000000'u64, xLow: 0x0000000000000002'u64, yHigh: 0x7fff000000000000'u64, yLow: 0x0000000000000001'u64, expectedHigh: 0xffff800000000000'u64, expectedLow: 0x0000000000000002'u64, expectedSignFlip: false, expectedHalfTie: false),
      PacketTwoBContractVector(operation: 1'u8, xHigh: 0xffff800000000000'u64, xLow: 0x0000000000000002'u64, yHigh: 0xffff800000000000'u64, yLow: 0x0000000000000002'u64, expectedHigh: 0xffff800000000000'u64, expectedLow: 0x0000000000000002'u64, expectedSignFlip: false, expectedHalfTie: false),
    ]

var
  packetTwoBVectorCount = 0
  packetTwoBRemainderSignFlipCount = 0
  packetTwoBRemainderHalfTieCount = 0
  packetTwoBFmodSignFlipCount = 0
  packetTwoBZeroSignCount = 0

for vector in packetTwoBContractVectors:
  let
    x = fromBits(
      vector.xHigh,
      vector.xLow,
    )
    y = fromBits(
      vector.yHigh,
      vector.yLow,
    )
    expected = fromBits(
      vector.expectedHigh,
      vector.expectedLow,
    )
    actual =
      if vector.operation == 0'u8:
        remainder(x, y)
      else:
        fmod(x, y)

  doAssert sameBits(
    actual,
    expected,
  )

  let
    actualNonzero = isFinite(actual) and not isZero(actual)
    actualSignFlip =
      actualNonzero and (signBit(actual) != signBit(x))

  doAssert actualSignFlip ==
    vector.expectedSignFlip

  if vector.expectedSignFlip:
    if vector.operation == 0'u8:
      inc packetTwoBRemainderSignFlipCount
    else:
      inc packetTwoBFmodSignFlipCount

  if vector.operation == 0'u8 and vector.expectedHalfTie:
    inc packetTwoBRemainderHalfTieCount

  if isFinite(actual) and isZero(actual):
    doAssert signBit(actual) == signBit(x)
    inc packetTwoBZeroSignCount

  inc packetTwoBVectorCount

doAssert packetTwoBVectorCount == 2048
doAssert packetTwoBRemainderSignFlipCount == 108
doAssert packetTwoBRemainderHalfTieCount == 36
doAssert packetTwoBFmodSignFlipCount == 0
doAssert packetTwoBZeroSignCount == 552

echo "FLOAT128_PACKET_TWO_B_CONTRACT_OK\t2048\t108\t36\t0\t552"
